/** Templates of files generated by the `ultracode init` command. */

export const HELLO_WORKFLOW = `/// <reference path="../workflow.d.ts" />
//
// Sample workflow. Run it with:
//   ultracode run hello --args '{"name":"Ondřej"}'
//
// The script has no imports: agent, parallel, pipeline, phase, log, args, budget and workflow are globals.
// \`meta\` must be a plain literal (no variables or function calls).

export const meta = {
  name: 'hello',
  description: 'Sample workflow: one agent greets and returns the answer as JSON.',
  whenToUse: 'Verifying that ultracode and \`agentiscode\` (claude -p) work.',
  phases: [
    { title: 'Greeting', detail: 'one agent returns the greeting as structured output' },
  ],
}

phase('Greeting')

const name = (args && args.name) || 'world'

const answer = await agent(
  'Greet the person named "' + name + '" in Czech in one short sentence. Do not use any tools.',
  {
    label: 'greeting',
    effort: 'low',
    schema: {
      type: 'object',
      properties: {
        greeting: { type: 'string', description: 'Greeting in one sentence' },
      },
      required: ['greeting'],
    },
  },
)

// agent() returns null when it fails – always handle that.
if (!answer) {
  log('Agent failed, the workflow has no result.')
  return { ok: false }
}

return { ok: true, greeting: answer.greeting }
`

